import os, json
import numpy as np

P_NOE_C = 'storage/noesis/latest_centers.txt'
P_NOE_R = 'storage/noesis/latest_radii.txt'
OUT = 'storage/noesis/nmap/quest_eval562_comparison_v2.json'

Q_BASE = 'storage/Quest/nmap/n26/noesis_data'
P_Q_BND = f'{Q_BASE}/quest_eval562_boundary_contacts.csv'
P_Q_T25 = f'{Q_BASE}/quest_eval562_top25_slack_1e9.csv'
P_Q_T15 = f'{Q_BASE}/quest_eval562_top15_slack_1e8.csv'

def safe_load_txt(path, shape=None):
    try:
        arr = np.loadtxt(path, dtype=float)
        if shape is not None:
            arr = arr.reshape(shape)
        return arr
    except Exception:
        return None

def read_csv(path):
    rows = []
    try:
        with open(path, 'r') as f:
            raw = [ln.strip() for ln in f.readlines() if ln.strip()]
        if not raw:
            return rows
        sep = ',' if raw[0].count(',') >= raw[0].count(';') else ';'
        hdr = [h.strip().lower() for h in raw[0].split(sep)]
        for ln in raw[1:]:
            parts = [p.strip() for p in ln.split(sep)]
            rec = {}
            for k, v in zip(hdr, parts):
                rec[k] = v
            rows.append(rec)
    except Exception:
        pass
    return rows

def parse_pairs(rows):
    pairs = set()
    for r in rows:
        keys = {k.lower(): v for k, v in r.items()}
        ii = None; jj = None
        for cand in ['i','disc_i','idx_i','u','a','p','p_i','disc','idx']:
            if cand in keys:
                try: ii = int(float(keys[cand])); break
                except: pass
        for cand in ['j','disc_j','idx_j','v','b','q','p_j']:
            if cand in keys:
                try: jj = int(float(keys[cand])); break
                except: pass
        if ii is None or jj is None:
            # fallback: first two numeric fields
            nums = []
            for v in keys.values():
                try: nums.append(int(float(v)))
                except: pass
            if len(nums) >= 2:
                ii, jj = nums[0], nums[1]
        if ii is None or jj is None or ii == jj:
            continue
        a, b = (ii, jj) if ii < jj else (jj, ii)
        pairs.add((a, b))
    return pairs

def parse_boundary_disc_side(rows):
    # returns set of (disc, side) if available, and side-only set
    disc_side = set()
    sides = set()
    for r in rows:
        keys = {k.lower(): v for k, v in r.items()}
        side = None
        for cand in ['side','s','dir']:
            if cand in keys:
                side = str(keys[cand]).strip()
                break
        if side is None:
            # attempt short string fallback
            for v in keys.values():
                if isinstance(v, str) and 1 <= len(v) <= 5:
                    side = v; break
        if side is None:
            continue
        lst = side.lower()
        if lst in ['xl','x_l','left','l']: norm = 'xL'
        elif lst in ['xr','x_r','right','r']: norm = 'xR'
        elif lst in ['yb','y_b','bottom','b']: norm = 'yB'
        elif lst in ['yt','y_t','top','t']: norm = 'yT'
        elif lst in ['xL','xR','yB','yT']: norm = lst
        else: 
            # skip unrecognized
            continue
        sides.add(norm)

        # disc index if present
        ii = None
        for cand in ['disc','i','idx','disc_i','idx_i']:
            if cand in keys:
                try: ii = int(float(keys[cand])); break
                except: pass
        if ii is not None:
            disc_side.add((ii, norm))
    return disc_side, sides

def compute_slacks(C, R):
    x = C[:,0]; y = C[:,1]; r = R
    s_xL = x - r
    s_xR = 1.0 - x - r
    s_yB = y - r
    s_yT = y - r
    s_yT = 1.0 - y - r
    D = C[:,None,:] - C[None,:,:]
    dist = np.sqrt(np.sum(D**2, axis=2))
    sp = dist - (r[:,None] + r[None,:])
    return (s_xL, s_xR, s_yB, s_yT), sp

def boundary_set_noesis(C, R, tol=1e-8):
    (s_xL, s_xR, s_yB, s_yT), _ = compute_slacks(C, R)
    S = set(); Sside = set()
    for i in range(len(R)):
        if s_xL[i] <= tol: S.add((i,'xL')); Sside.add('xL')
        if s_xR[i] <= tol: S.add((i,'xR')); Sside.add('xR')
        if s_yB[i] <= tol: S.add((i,'yB')); Sside.add('yB')
        if s_yT[i] <= tol: S.add((i,'yT')); Sside.add('yT')
    return S, Sside

def topk_pairs_by_rank(C, R, K, tol_interior=1e-8):
    (s_xL, s_xR, s_yB, s_yT), sp = compute_slacks(C, R)
    N = len(R)
    bmask = (s_xL <= tol_interior) | (s_xR <= tol_interior) | (s_yB <= tol_interior) | (s_yT <= tol_interior)
    items = []
    for i in range(N):
        if bmask[i]: continue
        for j in range(i+1, N):
            if bmask[j]: continue
            items.append((float(sp[i,j]), i, j))
    items.sort(key=lambda t: t[0])
    out = []
    seen = set()
    for s, i, j in items:
        a, b = (i, j) if i < j else (j, i)
        if (a, b) in seen: continue
        seen.add((a, b))
        out.append((a, b))
        if len(out) >= K: break
    return set(out)

def jaccard(A, B):
    inter = len(A & B)
    uni = len(A | B) if (A or B) else 1
    return {'intersection': inter, 'union': uni, 'jaccard': (inter/uni) if uni else 1.0}

def write_json(path, obj):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'w') as f:
        json.dump(obj, f, indent=2)

def construct_packing():
    C = safe_load_txt(P_NOE_C, shape=(26,2))
    R = safe_load_txt(P_NOE_R, shape=(26,))
    if C is None or R is None:
        # safe fallback
        centers = []
        for i in range(5):
            for j in range(6):
                if len(centers) < 26:
                    centers.append([0.1 + 0.2*i, 0.1 + 0.15*j])
        C = np.array(centers, float)
        R = np.full(26, 0.08, float)

    # Read Quest files
    q_bnd_rows = read_csv(P_Q_BND)
    q_t25_rows = read_csv(P_Q_T25)
    q_t15_rows = read_csv(P_Q_T15)
    Q_disc_side, Q_side = parse_boundary_disc_side(q_bnd_rows)
    Q_t25 = parse_pairs(q_t25_rows)
    Q_t15 = parse_pairs(q_t15_rows)

    N_disc_side, N_side = boundary_set_noesis(C, R, tol=1e-8)
    # Rank-based Top-K by smallest slack (interior-filtered at tol=1e-8)
    N_top25_rank = topk_pairs_by_rank(C, R, K=25, tol_interior=1e-8)
    N_top15_rank = topk_pairs_by_rank(C, R, K=15, tol_interior=1e-8)

    res = {
        'quest_eval_id': 562,
        'notes': {
            'quest_boundary_rows': len(q_bnd_rows),
            'boundary_has_disc_indices': (len(Q_disc_side) >= 10)  # heuristic
        },
        'boundary_disc_side': {
            'quest_size': len(Q_disc_side), 'noesis_size': len(N_disc_side),
            **jaccard(Q_disc_side, N_disc_side)
        },
        'boundary_side_only': {
            'quest_sides': sorted(list(Q_side)), 'noesis_sides': sorted(list(N_side)),
            **jaccard(Q_side, N_side)
        },
        'topK_slack_by_rank': {
            '1e-9_label_K25': {
                'quest_size': len(Q_t25), 'noesis_size': len(N_top25_rank),
                **jaccard(Q_t25, N_top25_rank)
            },
            '1e-8_label_K15': {
                'quest_size': len(Q_t15), 'noesis_size': len(N_top15_rank),
                **jaccard(Q_t15, N_top15_rank)
            }
        }
    }

    try:
        write_json(OUT, res)
    except Exception:
        pass

    # Return baseline snapshot with tiny shrink
    R_out = np.maximum(R - 1e-9, 1e-12)
    return C.astype(float), R_out.astype(float)
